arguments.command:
cd /tmp/sv-395ad3e3cb1e4db6b47aacbe273a7529/advanced-multi-complexity && dotnet package list --format json 2>/dev/null | python3 -m json.tool > after-cpm-packages.json && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: (project_basename, framework, package_id) -> (requested, resolved)
def build_index(data):
    idx = {}
    for p in data['projects']:
        proj = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                idx[(proj, fw['framework'], pkg['id'])] = (pkg['requestedVersion'], pkg['resolvedVersion'])
    return idx

b = build_index(baseline)
a = build_index(after)

changes = []
unchanged = []
all_keys = sorted(set(list(b.keys()) + list(a.keys())))
for key in all_keys:
    proj, fw, pkg_id = key
    if key in b and key in a:
        if b[key][1] != a[key][1]:
            changes.append((proj, fw, pkg_id, b[key][1], a[key][1], 'Version changed'))
        else:
            unchanged.append((proj, fw, pkg_id, a[key][1]))
    elif key in b and key not in a:
        changes.append((proj, fw, pkg_id, b[key][1], 'REMOVED', 'Removed'))
    else:
        changes.append((proj, fw, pkg_id, 'N/A', a[key][1], 'Added'))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'{c[0]} | {c[1]} | {c[2]} | {c[3]} -> {c[4]} | {c[5]}')
else:
    print('None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]} | {u[1]} | {u[2]} | {u[3]}')
"

